import {almaPreviewMarkup,mountAlmaPreview} from './alma-preview.js';
import {createProjectMotion} from './project-motion.js';
import {skillsPage} from './skills.js';
import {drawBinding} from './binding.js';
import {skills,discovery,previewCaptions,projectDescriptions,projectIndexLabels} from './discovery.js';
import {projects,about,categories,home,projectOrder,affiliations} from './content.js';
import {escape as e,caseURL,videoMarkup,article,contents,directory,utilityBar} from './render.js';
const content=document.querySelector('#work-content'),reader=document.querySelector('#reader'),status=document.querySelector('#selection-status');
const initialURL=new URL(location),motionStudy=!document.documentElement.dataset.release&&['artifact','reveal','prints'].includes(initialURL.searchParams.get('motion-study'));
const projectMotion=motionStudy?null:createProjectMotion(resumePreview);let state,scrollFrame,restoring=false,disposeAlma=()=>{};
const categoryPicker=document.querySelector('.category-picker'),phone=matchMedia('(max-width:900px)');
categoryPicker.open=!phone.matches;
phone.addEventListener('change',()=>{categoryPicker.open=!phone.matches;});
history.scrollRestoration='manual';
const reducedMotion=matchMedia('(prefers-reduced-motion: reduce)'),pausedPreviews=new Set();
const arrowIcon='<svg viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="M4 12h15m-6-6 6 6-6 6" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"/></svg>';
const documentIcon='<svg viewBox="0 0 32 40" fill="none" aria-hidden="true"><path d="M5 2h14l8 8v28H5V2Z M19 2v9h8 M10 18h12 M10 24h12 M10 30h8" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/></svg>';
function projectThumb(id){const p=projects[id],src=p.image||p.video?.poster||p.artifact?.[0];return src?`<span class="project-thumb ${p.image?'is-sketch':''}"><img src="${src}" alt="" loading="lazy"></span>`:`<span class="project-thumb is-document">${documentIcon}</span>`;}
function startPreview(v){if(motionStudy||projectMotion?.active)return;const key=v.closest('[data-media]')?.dataset.media;if(!v.isConnected||state.view!=='map'||document.hidden||reducedMotion.matches||pausedPreviews.has(key)||!v.paused||v.error)return;v.play().then(()=>{if(!v.isConnected||document.hidden||reducedMotion.matches)v.pause();}).catch(()=>{/* Autoplay may be blocked; the visible Play demo control remains. */});}
function resumePreview(){const v=document.querySelector('#preview video');if(v){const r=v.getBoundingClientRect();if(r.top<innerHeight&&r.bottom>0)startPreview(v);}}
function parseURL(){const u=new URL(location),id=u.searchParams.get('project')||(projects[u.hash.slice(1)]?u.hash.slice(1):null),requested=u.searchParams.get('path'),view=u.searchParams.get('view')||(u.hash==='#about'?'about':null),skill=u.searchParams.get('skill');const valid=!!projects[id],invalid=!!id&&!valid;let path=categories[requested]||requested==='skills'?requested:'all';if(view==='case'&&valid)path=home(id);if(view==='skills')path='skills';return {path,experience:affiliations[u.searchParams.get('experience')]?u.searchParams.get('experience'):null,skill:skills[skill]?skill:'all',project:valid?id:'alma',view:view==='skills'||path==='skills'?'skills':view==='about'?'about':view==='case'&&valid?'case':'map',origin:null,scroll:0,focus:null,unknown:invalid};}
function href(s,hash){const u=new URL(location);u.searchParams.delete('v');if(s.experience)u.searchParams.set('experience',s.experience);else u.searchParams.delete('experience');if(s.path==='all')u.searchParams.delete('path');else u.searchParams.set('path',s.path);if(s.skill&&s.skill!=='all')u.searchParams.set('skill',s.skill);else u.searchParams.delete('skill');u.searchParams.set('project',s.project);if(s.view==='map')u.searchParams.delete('view');else u.searchParams.set('view',s.view);u.hash=hash||(s.view==='case'?`case-${s.project}`:s.view==='about'?'about':s.view==='skills'?'skills-heading':'map');return u;}
function focusID(){return document.activeElement?.id||(state?.view==='case'?(location.hash.slice(1)||'case-'+state.project):state?.view==='about'?'about':state?.view==='skills'?'skills-heading':null);}
function snapshot(){return {...state,scroll:window.scrollY,listScroll:document.querySelector('#selected-work')?.scrollTop||0,focus:focusID(),viewportWidth:innerWidth,aboutOpen:!!document.querySelector('.about-experience')?.open,skillOpen:[...document.querySelectorAll('.skill-group[open],.skill-more[open]')].map(n=>n.id)};}
function remember(){state=snapshot();history.replaceState(state,'');}
function pauseMedia(){document.querySelectorAll('video').forEach(v=>v.pause());}
function defaultOrigin(){return {path:'all',experience:null,skill:'all',project:state.project,view:'map',origin:null,scroll:0,focus:`select-${state.project}`};}
function go(next,{hash,restore=false,target}={}){projectMotion?.cancel();remember();pauseMedia();state=next;history.pushState(state,'',href(state,hash));render();position({restore,target:target||hash});}
function position({restore=false,target}={}){restoring=true;requestAnimationFrame(()=>{if(restore){document.getElementById(state.focus)?.focus({preventScroll:true});window.scrollTo({top:state.scroll||0,behavior:'instant'});}else if(state.view!=='map'||target){const rawTarget=target?.replace(/^#/,'');const id=(projects[rawTarget]?'selected-project':rawTarget==='work'?'all-work-heading':rawTarget)||(state.view==='all'?'all-work-heading':state.view==='about'?'about':state.view==='skills'?'skills-heading':`case-${state.project}`);const el=document.getElementById(id)||reader.querySelector('h2');el?.focus({preventScroll:true});if(['case-'+state.project,'about'].includes(id))reader.scrollIntoView({block:'start',behavior:'instant'});else if(state.view==='skills'&&!phone.matches)window.scrollTo({top:0,behavior:'instant'});else el?.scrollIntoView({block:'start',behavior:'instant'});}restoring=false;remember();});}
function openCase(id){const origin=state.view==='case'?state.origin||defaultOrigin():snapshot();go({path:home(id),skill:state.skill||'all',project:id,view:'case',origin,scroll:0,focus:null});}
function returnToMap(){const origin=state.origin||defaultOrigin();go({...origin},{restore:true});}
function allWork(){go({path:'all',experience:null,skill:'all',project:state.project,view:'map',origin:null,unknown:false,scroll:0,focus:'path-all'},{restore:true});}
const ordered=projectOrder;
function matches(){return ordered.filter(id=>(state.path==='all'||state.path==='skills'||categories[state.path]?.projects.includes(id))&&(!state.experience||affiliations[state.experience]?.projects.includes(id))&&(state.skill==='all'||discovery[id].skills.includes(state.skill)));}
function renderMap(){
 state.skill=skills[state.skill]?state.skill:'all';state.path=categories[state.path]||state.path==='skills'?state.path:'all';
 const ids=matches();if(ids.length&&!ids.includes(state.project)&&state.view==='map')state.project=ids[0];
 document.querySelectorAll('.category-tabs [data-path]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.path===state.path)));
 document.querySelectorAll('[data-affiliation]').forEach(b=>b.setAttribute('aria-current',b.dataset.affiliation===state.experience?'true':'false'));
 document.querySelector('#clear-filters').hidden=state.path==='all'&&state.skill==='all'&&!state.experience;
 const title=state.experience?affiliations[state.experience].label:state.path==='all'?'Explore projects':state.path==='skills'?(skills[state.skill]||'Skills'):categories[state.path].label;
 document.querySelector('#all-work-heading').textContent=title;
 document.querySelector('#category-current').textContent=state.path==='skills'?'Skills':state.path==='all'?'All projects':categories[state.path].label;
 document.querySelector('#project-count').textContent=ids.length+' '+(ids.length===1?'project':'projects');
 content.innerHTML=`${state.unknown?'<p class="unknown-note">Project not found. Choose one below.</p>':''}<div class="work-grid">${ids.length?ids.map(id=>`<button class="work-entry ${state.project===id?'is-selected':''}" data-project="${id}" id="select-${id}" aria-pressed="${id===state.project}" aria-controls="preview" aria-label="${e(projects[id].title)} — ${e(projectDescriptions[id])}"><span class="project-card-heading">${projectThumb(id)}<span class="project-card-copy"><span class="work-title">${e(projects[id].title)}</span><span class="work-description">${e(projectIndexLabels[id])}</span></span></span><span class="project-indicator" aria-hidden="true">${state.project===id?'<span class="selected-mark"></span>':''}</span></button>`).join(''):'<div class="empty-state"><h3>No matching projects.</h3><button class="utility" data-clear>Clear filters</button></div>'}</div>`;
 const preview=document.querySelector('#preview');preview.hidden=!ids.length;if(!ids.length){preview.replaceChildren();return;}
 const p=projects[state.project];
 const visual=state.project==='alma'?almaPreviewMarkup():p.video?videoMarkup(p,'preview-'+state.project,{sketch:p.image,caption:previewCaptions[state.project]}):p.image?`<figure class="preview-sketch"><img src="${p.image}" alt="Editorial pencil illustration for ${e(p.title)}"><figcaption>Editorial sketch</figcaption></figure>`:p.artifact?`<figure class="preview-artifact"><a href="${p.artifact[0]}" target="_blank" rel="noopener" aria-label="Open ${e(p.title)} image (new tab)"><img src="${p.artifact[0]}" alt="${e(p.artifact[1])}"></a><figcaption>${e(p.artifact[1])}</figcaption></figure>`:'';
 preview.classList.toggle('is-written',!visual);
 preview.innerHTML=`<header class="preview-heading"><button class="choose-project utility" data-choose>Choose project</button><h2 class="preview-title" id="selected-project" tabindex="-1">${e(p.title)}</h2></header><p class="preview-definition">${e(projectDescriptions[state.project])}</p><div class="preview-visual">${visual}</div><div class="preview-actions actions">${p.action?`<a class="action open-project" href="${p.action[1]}" target="_blank" rel="noopener">${e(p.action[0])}${arrowIcon}<span class="sr-only"> (new tab)</span></a>`:''}<a class="read-more" id="read-${state.project}" href="${caseURL(state.project)}" data-case="${state.project}">Read more</a></div><div class="preview-footer"><p class="preview-note">${e(discovery[state.project].note)}</p></div>`;


}
function render(){disposeAlma();state.version=5;const returnLabel=state.origin?.view==='skills'?'Back to Skills':state.origin?.view==='about'?'Back to About':'Back to work';mediaObserver.disconnect();renderMap();document.querySelector('.work-page').hidden=state.view!=='map';const skillPage=document.querySelector('#skills-page');skillPage.hidden=state.view!=='skills';skillPage.innerHTML=state.view==='skills'?skillsPage():'';for(const id of state.skillOpen||[]){const item=skillPage.querySelector('#'+id);if(item)item.open=true;}reader.hidden=state.view==='map'||state.view==='skills';if(reader.hidden)reader.replaceChildren();else reader.innerHTML=utilityBar({compact:true,returnLabel})+(state.view==='all'?`${state.unknown?'<p class="unknown-note" role="status">That project link wasn’t found. Choose a project below.</p>':''}${directory()}`:`<div class="reader-layout ${state.view==='about'?'about-layout':''}">${state.view==='about'?'':contents(state.project)}${article(state.view==='about'?'about':state.project,{returnLabel})}</div>`);if(state.view==='about'&&state.aboutOpen)reader.querySelector('.about-experience').open=true;if(matchMedia('(max-width:800px)').matches)reader.querySelector('.contents')?.removeAttribute('open');document.body.dataset.view=state.view;const skip=document.querySelector('.skip-link');skip.href='#'+(state.view==='map'?'selected-work':state.view==='skills'?'skills-heading':state.view==='about'?'about':`case-${state.project}`);skip.textContent=state.view==='map'?'Skip to projects':state.view==='skills'?'Skip to skills':state.view==='about'?'Skip to About':'Skip to case study';document.querySelector('#read-about').setAttribute('aria-current',state.view==='about'?'page':'false');wireMedia();if(state.view==='map')disposeAlma=mountAlmaPreview(document.querySelector('#preview'));document.querySelector('#selected-work').scrollTop=state.listScroll||0;document.querySelectorAll('video').forEach(v=>mediaObserver.observe(v));document.dispatchEvent(new Event('notebookview'));requestAnimationFrame(drawBinding);}
function wireMedia(){document.querySelectorAll('[data-media]').forEach(fig=>{const v=fig.querySelector('video'),play=fig.querySelector('[data-play]'),sound=fig.querySelector('[data-sound]'),seek=fig.querySelector('[data-seek]'),full=fig.querySelector('[data-fullscreen]'),error=fig.querySelector('.media-error');if(!play)return;v.muted=true;v.defaultMuted=true;v.loop=!!fig.closest('#preview');v.preload=fig.closest('#preview')?'metadata':'none';
 const time=t=>`${Math.floor((t||0)/60)}:${String(Math.floor((t||0)%60)).padStart(2,'0')}`;
 function update(){const label=v.ended?'Replay demo':v.paused?'Play demo':'Pause demo';fig.querySelectorAll('[data-play]').forEach(b=>{b.querySelector('span').textContent=label;b.setAttribute('aria-label',label+' — '+v.getAttribute('aria-label').split(' — ')[0]);const icon=b.querySelector('svg');if(icon)icon.innerHTML=!v.paused?'<path d="M5 3h4v14H5zm7 0h4v14h-4z" fill="currentColor"/>':'<path d="m6 3 11 7-11 7Z" fill="currentColor"/>';});if(!v.paused)fig.dataset.started='true';sound.textContent=fig.dataset.silent==='true'?'No audio':v.muted?'Sound off':'Sound on';sound.setAttribute('aria-pressed',String(!v.muted));fig.querySelector('.media-time').textContent=`${time(v.currentTime)}${Number.isFinite(v.duration)?' / '+time(v.duration):''}`;seek.value=Number.isFinite(v.duration)?100*v.currentTime/v.duration:0;seek.parentElement.style.setProperty('--progress',String(Number(seek.value)/100));seek.setAttribute('aria-valuetext',`${time(v.currentTime)}${Number.isFinite(v.duration)?' of '+time(v.duration):''}`);}
 function failed(message){v.pause();error.hidden=false;if(message)error.firstChild.textContent=message+' ';fig.querySelectorAll('[data-play] span').forEach(label=>label.textContent='Retry video');}
 fig.querySelectorAll('[data-play]').forEach(button=>button.addEventListener('click',async()=>{projectMotion?.cancel();if(!v.paused){if(fig.closest('#preview'))pausedPreviews.add(fig.dataset.media);v.pause();update();return;}if(fig.closest('#preview'))pausedPreviews.delete(fig.dataset.media);pauseMedia();if(v.error)v.load();try{await v.play();error.hidden=true;}catch{failed('Video unavailable. The still and written description remain available.');}}));
 sound.addEventListener('click',()=>{v.muted=!v.muted;update();});
 const fullscreenUnavailable=()=>{error.hidden=false;error.firstChild.textContent='Fullscreen is unavailable here. The inline player still works. ';};
 full.addEventListener('click',async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else if(fig.querySelector('.taped-video').requestFullscreen)await fig.querySelector('.taped-video').requestFullscreen();else if(v.webkitEnterFullscreen)v.webkitEnterFullscreen();else fullscreenUnavailable();}catch{fullscreenUnavailable();}});
 seek.addEventListener('input',()=>{seek.parentElement.style.setProperty('--progress',String(Number(seek.value)/100));if(Number.isFinite(v.duration)){v.currentTime=Number(seek.value)*v.duration/100;update();}});
 for(const event of ['play','pause','ended','timeupdate','loadedmetadata','volumechange'])v.addEventListener(event,update);
 v.addEventListener('error',()=>failed());v.querySelector('source').addEventListener('error',()=>failed());
 });}
document.addEventListener('click',ev=>{const b=ev.target.closest('a,button');if(!b||ev.ctrlKey||ev.metaKey||ev.shiftKey||ev.altKey||ev.button)return;
 if(b.matches('[data-path]')){if(phone.matches)categoryPicker.open=false;if(b.dataset.path==='skills'){ev.preventDefault();go({...state,path:'skills',skill:'all',experience:null,view:'skills',origin:snapshot(),scroll:0,focus:'skills-heading'},{target:'skills-heading'});return;}if(b.dataset.path==='all'){ev.preventDefault();allWork();return;}go({...state,path:b.dataset.path,experience:null,skill:'all',view:'map',origin:null,unknown:false,scroll:window.scrollY,focus:'path-'+b.dataset.path});document.getElementById('path-'+state.path)?.focus({preventScroll:true});status.textContent=`${matches().length} projects shown`;}
 else if(b.matches('[data-affiliation]')){ev.preventDefault();go({...state,path:'all',skill:'all',experience:b.dataset.affiliation,view:'map',origin:null,scroll:0,focus:'all-work-heading'},{target:'all-work-heading'});status.textContent=`${matches().length} associated projects shown`;}
 else if(b.matches('[data-skill]')){go({...state,skill:state.skill===b.dataset.skill?'all':b.dataset.skill,view:'map',origin:null,scroll:window.scrollY,focus:b.id});document.getElementById(b.id)?.focus({preventScroll:true});status.textContent=`${matches().length} projects shown`;}
 else if(b.matches('[data-project]')){projectMotion?.cancel();const transfer=projectMotion?.capture(b,ev);const listScroll=document.querySelector('#selected-work').scrollTop;go({...state,listScroll,project:b.dataset.project,view:'map',origin:null,scroll:window.scrollY,focus:b.id});document.getElementById(b.id)?.focus({preventScroll:true});document.querySelector('#selected-project').focus({preventScroll:true});requestAnimationFrame(()=>{if(!matchMedia('(min-width:1200px)').matches)document.querySelector('#preview').scrollIntoView({block:'start',behavior:'instant'});});projectMotion?.start(transfer);status.textContent=projects[state.project].title+' preview selected';}
 else if(b.matches('[data-choose]')){const target=document.getElementById('select-'+state.project)||document.querySelector('#selected-work');target.focus({preventScroll:true});target.scrollIntoView({block:'start',behavior:'instant'});}
 else if(b.matches('[data-preview-return]')){const target=document.getElementById('select-'+state.project);target?.focus({preventScroll:true});target?.scrollIntoView({block:'center',behavior:'instant'});}
 else if(b.matches('[data-case]')){ev.preventDefault();openCase(b.dataset.case);}
 else if(b.matches('[data-about]')){ev.preventDefault();go({...state,view:'about',origin:snapshot(),scroll:0,focus:null});}
 else if(b.matches('[data-return]')){ev.preventDefault();returnToMap();}
 else if(b.matches('[data-all],#all-work,[data-clear],#clear-filters')){ev.preventDefault();allWork();status.textContent='All 13 projects shown';}
 else if(b.matches('[data-section]')){ev.preventDefault();history.replaceState(state,'',href(state,b.hash));const target=document.getElementById(b.hash.slice(1));target?.focus({preventScroll:true});target?.scrollIntoView({block:'start',behavior:'instant'});}
});
document.querySelectorAll('.category-tabs [data-path]').forEach(b=>b.id='path-'+b.dataset.path);
window.addEventListener('popstate',()=>{projectMotion?.cancel();pauseMedia();state=history.state?.version===5?history.state:parseURL();if(state.view==='all')state.view='map';render();position({restore:!!history.state?.view,target:location.hash});});
window.addEventListener('scroll',()=>{cancelAnimationFrame(scrollFrame);scrollFrame=requestAnimationFrame(()=>{if(!restoring)remember();});},{passive:true});
document.addEventListener('visibilitychange',()=>{if(document.hidden)pauseMedia();else{const v=document.querySelector('#preview video');if(v){const r=v.getBoundingClientRect();if(r.top<innerHeight&&r.bottom>0)startPreview(v);}}});
reducedMotion.addEventListener('change',()=>{if(reducedMotion.matches)pauseMedia();});
const mediaObserver=new IntersectionObserver(entries=>entries.forEach(x=>{const preview=!!x.target.closest('#preview');if(!x.isIntersecting||(preview&&x.intersectionRatio<.25))x.target.pause();else if(preview)startPreview(x.target);}),{threshold:[0,.25]});
document.querySelector('h1').tabIndex=-1;
state=history.state?.version===5?history.state:parseURL();if(state.view==='all')state.view='map';render();history.replaceState(state,'',initialURL.searchParams.has('path')||initialURL.searchParams.has('view')||initialURL.searchParams.has('project')?href(state,initialURL.hash):location.href);
if(state.view!=='map'||initialURL.hash&&initialURL.hash!=='#map')document.fonts.ready.then(()=>position({restore:!!state.scroll&&state.viewportWidth===innerWidth,target:initialURL.hash}));
let currentWidth=innerWidth;window.addEventListener('resize',()=>{drawBinding();if(innerWidth!==currentWidth&&state.view!=='map')position({target:location.hash});currentWidth=innerWidth;});drawBinding();

if(motionStudy)import('./motion-studies.js');
